// Package: Microsoft.Extensions.AI --version 9.*
// Package: Microsoft.Extensions.AI.OpenAI --version 9.*

using Microsoft.Extensions.AI;

public sealed class TokenBudgetService
{
    private readonly IChatClient _chatClient;

    public TokenBudgetService(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<ChatResponse> GenerateWithBudgetAsync(
        string prompt,
        int maxInputTokens = 4096,
        int maxOutputTokens = 1024,
        decimal maxCostUsd = 0.05m,
        CancellationToken ct = default)
    {
        // Get the built-in tokenizer from the chat client
        var tokenizer = _chatClient.GetService<ITokenizer>()
            ?? throw new InvalidOperationException("Chat client does not provide a tokenizer.");

        // Count input tokens before sending
        var inputTokens = tokenizer.CountTokens(prompt);
        if (inputTokens > maxInputTokens)
            throw new InvalidOperationException(
                $"Prompt exceeds input token budget: {inputTokens} > {maxInputTokens}");

        var options = new ChatOptions { MaxOutputTokens = maxOutputTokens, Temperature = 0.2f };
        var response = await _chatClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            options,
            ct);

        // Read actual token usage from the response
        var usage = response.Usage ?? TokenUsage.Zero;
        var estimatedCost = EstimateCost(usage.InputTokenCount, usage.OutputTokenCount);

        if (estimatedCost > maxCostUsd)
            throw new InvalidOperationException(
                $"Estimated cost {estimatedCost:C} exceeds budget {maxCostUsd:C}");

        return response;
    }

    private static decimal EstimateCost(int inputTokens, int outputTokens)
    {
        const decimal inputRatePerM = 0.00015m;
        const decimal outputRatePerM = 0.00060m;
        return (inputTokens * inputRatePerM + outputTokens * outputRatePerM) / 1_000_000m;
    }
}

// Sample usage
var chatClient = new OpenAIClient("your-api-key").AsChatClient("gpt-4o-mini");
var budgetService = new TokenBudgetService(chatClient);

var response = await budgetService.GenerateWithBudgetAsync(
    prompt: "Explain RAG in 2 sentences.",
    maxInputTokens: 4096,
    maxOutputTokens: 256,
    maxCostUsd: 0.10m);

Console.WriteLine($"Input tokens: {response.Usage?.InputTokenCount}, Output tokens: {response.Usage?.OutputTokenCount}");
// Expected output: Input tokens: 12, Output tokens: 45
